import hashlib,json,os,pathlib,stat
ROOT=pathlib.Path("/private/tmp/chain-P1-sparse-checkout-closed-results-20261114-v1")
assert ROOT.is_dir() and not ROOT.is_symlink() and str(ROOT.resolve())==str(ROOT)
for n in ["official-transfer-v1","official-transfer-v1/parts","package","root-closed-tool-records-v1"]:
 (ROOT/n).mkdir(mode=0o700)
F=os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC
def fp(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
def read(path):
 p=pathlib.Path(path);assert str(p.resolve())==str(p)
 a=p.lstat();assert stat.S_ISREG(a.st_mode) and a.st_nlink==1 and a.st_size<=65536
 fd=os.open(p,F)
 try:
  assert fp(os.fstat(fd))==fp(a)
  pieces=[]
  while True:
   b=os.read(fd,65536)
   if not b:break
   pieces.append(b)
  data=b"".join(pieces)
  assert len(data)==a.st_size and fp(os.fstat(fd))==fp(a)==fp(p.lstat())
  return data
 finally:os.close(fd)
def put(path,data):
 with path.open("xb") as f:f.write(data);f.flush();os.fsync(f.fileno())
 assert read(path)==data
